rules.badExample:
package EV {
  part def Driver
  part def RoadEnvironment;
}

rules.goodExample:
package EV {
  // 单行声明：用分号结束
  part def Driver;
  part def RoadEnvironment;

  // 带内部成员：用花括号包住
  part def ElectricVehicle {
    part driver : Driver;
  }
}

rules.badExample:
package EV {
  part def Wheel
  part wheel : Wheel;
}

rules.goodExample:
package EV {
  // 单行声明：用分号结束
  part def Wheel;

  // 定义块：用花括号包住内部成员
  part def BatteryPack {
    part cell;
  }

  part wheel : Wheel;
}

rules.badExample:
package EV {
  part def BatteryPack;

  part def ElectricVehicle {
    part battery : {{missingName}};
  }
}

rules.goodExample:
package EV {
  part def BatteryPack;

  part def ElectricVehicle {
    // 路径 A：如果是拼写错，改回已有类型
    part battery : BatteryPack;
  }
}

package EV_NewType {
  // 路径 B：如果确实需要新类型，先定义它
  part def {{missingName}};

  part def ElectricVehicle {
    part battery : {{missingName}};
  }
}

package EV {
  requirement def VehicleNeed;
  part def ElectricVehicle;

  requirement usableRange : VehicleNeed;
  part evPreview : ElectricVehicle;

  // satisfy 连接的是上面已经存在的两个 usage
  satisfy usableRange by evPreview;

  view reviewView : StandardViewDefinitions::GeneralView {
    // expose 也只能选择已经存在的模型元素
    expose usableRange;
    expose evPreview;
  }
}

rules.badExample:
part def ElectricVehicle {
  interface powerLink : BatteryToInverter connect battery.dcOut to inverter.dcIn;
  interface powerLink : BatteryToInverter connect battery.dcOut to inverter.dcIn;
}

rules.goodExample:
part def ElectricVehicle {
  interface powerLink : BatteryToInverter connect battery.dcOut to inverter.dcIn;
  interface commandLink : ControllerToInverter connect controller.commandOut to inverter.commandIn;
}

package EV {
  port def PowerPort;
  part def BatteryPack { port dcOut : PowerPort; }
  part def Motor { port powerIn : PowerPort; }

  part def ElectricVehicle {
    part battery : BatteryPack;
    part motor : Motor;
    connect battery.dcOut to motor.powerIn;
  }
}

package EV {
  item def ElectricalPower;
  port def PowerPort { ref item power : ElectricalPower; }

  part def BatteryPack { port dcOut : PowerPort; }
}

rules.badExample:
package EV {
  port def PowerPort;
  part def ElectricVehicle {
    part inlet : PowerPort;
  }
}

rules.goodExample:
package EV {
  port def PowerPort;
  part def ChargeInlet { port plug : PowerPort; }

  part def ElectricVehicle {
    part inlet : ChargeInlet;
    port dcIn : PowerPort;
  }
}

rules.badExample:
package EV {
  item def ElectricalPower;
  port def PowerPort { ref item power : ElectricalPower; }
  interface def PowerInterface {
    end source : PowerPort;
    end target : PowerPort;
    flow source.power target.power;
  }
}

rules.goodExample:
package EV {
  item def ElectricalPower;
  port def PowerPort { ref item power : ElectricalPower; }

  interface def PowerInterface {
    end source : PowerPort;
    end target : PowerPort;
    flow source.power to target.power;
  }
}

package EV {
  port def PowerPort;
  interface def PowerInterface {
    end source : PowerPort;
    end target : PowerPort;
  }
}

rules.badExample:
package EV {
  part def ElectricVehicle {
    attribute massKg = 1200.0;
  }
}

rules.goodExample:
package EV {
  part def ElectricVehicle {
    attribute massKg : ScalarValues::Real = 1200.0;
    attribute usableEnergyKWh : ScalarValues::Real = 72.0;
  }
}

package EV {
  requirement def RangeNeed {
    attribute minRangeKm : ScalarValues::Real = 400.0;
  }

  requirement usableRange : RangeNeed {
    attribute :>> minRangeKm = 480.0;
  }
}

rules.badExample:
package EV {
  action def DriveCycle;
  part def VehicleController;
  perform DriveCycle by controller;
}

rules.goodExample:
package EV {
  action def DriveCycle;

  part def VehicleController {
    perform action driveControl : DriveCycle;
  }

  part controller : VehicleController;
}

rules.badExample:
package EV {
  part def ElectricVehicle;
  part evPrototype : ElectricVehicle;

  requirement def VehicleNeed {
    subject vehicle : ElectricVehicle;
  }

  requirement usableRange : VehicleNeed {
    subject vehicle = evPrototype;
  }

  satisfy usableRange by evPrototype;
}

rules.goodExample:
package EV {
  part def ElectricVehicle;
  part evPrototype : ElectricVehicle;

  requirement def VehicleNeed {
    subject vehicle : ElectricVehicle;
  }

  requirement usableRange : VehicleNeed;
  satisfy usableRange by evPrototype;
}

package EV {
  requirement def VehicleNeed;
  part def ElectricVehicle;

  requirement usableRange : VehicleNeed;
  part evPreview : ElectricVehicle;

  satisfy usableRange by evPreview;
}
